async function moveTo(x: number, z: number, tolerance: number = 2) {
    let prevPos = "-1,-1";
    let stuckCount = 0;
    while(true) {
        const p = sdk.getState()?.player;
        if (!p) break;
        if (Math.abs(p.worldX - x) <= tolerance && Math.abs(p.worldZ - z) <= tolerance) {
            console.log(`Arrived at ${p.worldX}, ${p.worldZ}`);
            break;
        }

        const curPos = `${p.worldX},${p.worldZ}`;
        if (curPos === prevPos) stuckCount++;
        else { stuckCount = 0; prevPos = curPos; }

