import { BotSDK } from "/app/sdk/index.ts";
import { BotActions } from "/app/sdk/actions.ts";

const sdk = new BotSDK({ botUsername: "agent", password: "test", gatewayUrl: "ws://localhost:7780", autoLaunchBrowser: false });
async function main() {
  await sdk.connect();
  const bot = new BotActions(sdk);
  console.log("Walking inside...");
  await bot.walkTo(3211, 3213, 0);

  const rawFood = sdk.getInventory().find(i => /^raw/i.test(i.name));
  const range = sdk.getState().nearbyLocs.find(l => /range/i.test(l.name));
  console.log("Cooking on", range?.name, "from inside!");

  if (rawFood && range) {
      const res = await sdk.sendUseItemOnLoc(rawFood.slot, range.x, range.z, range.id);
      console.log("Sent cook command:", res);
      await sdk.waitForTicks(5);
      console.log("Messages:", sdk.getState().gameMessages.slice(-2));
      const cooked = sdk.getInventory().find(i => /^shrimps$/i.test(i.name));
      console.log("Has cooked shrimps:", !!cooked);
  }
  process.exit(0);
}
main();

