let state = sdk.getState();
const ores = state.inventory.filter(i => /ore$/i.test(i.name));
for (const ore of ores) {
  sdk.sendDropItem(ore.slot); // don't await, just send
}
await sdk.waitForTicks(ores.length + 1);
state = sdk.getState();
const finalLength = state.inventory.filter(i => /ore$/i.test(i.name)).length;
return `Initial: ${ores.length}, Final: ${finalLength}`;

let state = sdk.getState();
const rocks = state.nearbyLocs.filter(loc => /Rocks (iron|tin|copper) ore/i.test(loc.name)).sort((a,b)=>b.distance-a.distance); // furthest rock
if (rocks.length > 0) {
  const rock = rocks[0];
  const mineOpt = rock.optionsWithIndex.find(o => /^mine$/i.test(o.text));
  await sdk.sendInteractLoc(rock.x, rock.z, rock.id, mineOpt.opIndex);

  // wait 1 tick, then drop an item
  await sdk.waitForTicks(1);
  const ores = sdk.getInventory().filter(i => /ore$/i.test(i.name));
  if (ores.length > 0) {
    await sdk.sendDropItem(ores[0].slot);
  }

  // wait for mining
  await sdk.waitForTicks(5);
  return sdk.getState().player.animId;
}
